import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO
def task_func(url, table_id):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.HTTPError(f"Request failed: {e}")

    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', id=table_id)

    if table is None:
        raise ValueError("Table with the specified ID not found.")

    headers = []
    header_row = table.find('tr')
    if header_row:
        headers = [th.get_text(strip=True) for th in header_row.find_all('th')]

    data = []
    rows = table.find_all('tr')

    if not headers and rows:
        first_row_cells = rows[0].find_all(['td', 'th'])
        if all(cell.name == 'th' for cell in first_row_cells):
            headers = [cell.get_text(strip=True) for cell in first_row_cells]
            start_row_index = 1
        else:
            start_row_index = 0
    else:
        start_row_index = 1 if headers else 0

    for row in rows[start_row_index:]:
        cols = row.find_all('td')
        if cols:
            cols = [ele.get_text(strip=True) for ele in cols]
            data.append(cols)

    if not headers and data:
        num_cols = len(data[0])
        headers = [f'Column_{i+1}' for i in range(num_cols)]

    df = pd.DataFrame(data, columns=headers)
    return df

