import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not webpage_url or not database_name:
        raise ValueError("Webpage URL and database name cannot be empty.")

    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
        html_content = response.text
    except requests.RequestException as e:
        raise requests.RequestException(f"Network issue accessing URL: {e}")

    try:
        tree = html.fromstring(html_content)
        table_elements = tree.xpath("//table")

        if not table_elements:
            return 0

        table = table_elements[0]
        data = []
        headers = []

        header_row = table.xpath(".//th")
        if header_row:
            headers = [th.text_content().strip() for th in header_row]

        for row in table.xpath(".//tr"):
            cols = [td.text_content().strip() for td in row.xpath(".//td")]
            if cols:
                data.append(cols)

        if not data:
            return 0

        df = pd.DataFrame(data, columns=headers if headers else None)

    except Exception as e:
        return 0

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        rows_stored = len(df)
        conn.close()
        return rows_stored
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

