            verify_cert = False if endpoint_legacy_compatible else True
            response = requests.get(url, verify=verify_cert)
            response.raise_for_status()
            content = response.text
        except requests.exceptions.RequestException as e:
            raise ConnectionError(f"Error fetching URL {url}: {e}")

    soup = bs4.BeautifulSoup(content, 'html.parser')
    text = soup.get_text()

    phone_numbers = re.findall(r'\+?\d{1,3}[-.\s]?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}', text)

    try:
